BEGIN;
SELECT no_plan();
SELECT ok(NOT has_function_privilege('anon', 'create_subscription_checkout(uuid,uuid,text)', 'EXECUTE'), 'anonymous checkout denied');
SELECT ok(NOT has_function_privilege('authenticated', 'mark_invoice_paid(uuid,text,text)', 'EXECUTE'), 'buyer cannot mark paid');
SELECT ok(NOT has_function_privilege('authenticated', 'record_provider_payment(text,text,uuid,integer,text,text,text,jsonb)', 'EXECUTE'), 'buyer cannot impersonate provider');
SELECT ok(NOT has_table_privilege('authenticated', 'billing_checkout_settings', 'SELECT,INSERT,UPDATE,DELETE'), 'buyer cannot enable checkout');
SELECT ok(NOT has_table_privilege('authenticated', 'subscription_checkout_requests', 'SELECT,INSERT,UPDATE,DELETE'), 'receipts private');
SELECT ok(NOT has_function_privilege('authenticated', 'billing_owner_org()', 'EXECUTE'), 'owner helper private');
SELECT is((SELECT mode FROM billing_checkout_settings), 'disabled', 'checkout disabled after migration');
INSERT INTO orgs(id,name) VALUES ('81000000-0000-4000-8000-000000000001','Checkout A'), ('81000000-0000-4000-8000-000000000002','Checkout B');
INSERT INTO locations(id,org_id,name) VALUES
 ('82000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','Main'),
 ('82000000-0000-4000-8000-000000000002','81000000-0000-4000-8000-000000000002','Other');
INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES
 ('83000000-0000-4000-8000-000000000001','checkout-a@example.test','{"org_id":"81000000-0000-4000-8000-000000000001"}'),
 ('83000000-0000-4000-8000-000000000002','checkout-b@example.test','{"org_id":"81000000-0000-4000-8000-000000000002"}');
INSERT INTO organization_members(org_id,auth_user_id,role) VALUES
 ('81000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000001','owner'),
 ('81000000-0000-4000-8000-000000000002','83000000-0000-4000-8000-000000000002','owner');
INSERT INTO product_prices(product,amount_agorot,effective_from) VALUES ('menu',4900,NOW());
CREATE TEMP TABLE checkout_results(key TEXT PRIMARY KEY, value JSONB);
GRANT ALL ON checkout_results TO authenticated, service_role;
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claims = '{"sub":"83000000-0000-4000-8000-000000000001","app_metadata":{"org_id":"81000000-0000-4000-8000-000000000001"}}';
SELECT is(get_subscription_catalog()->>'mode','disabled','owner sees disabled mode');
SELECT throws_ok($$SELECT create_subscription_checkout('84000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','menu')$$,'P0001','checkout_disabled','cannot order placeholder prices without configuration');
RESET ROLE;
UPDATE billing_checkout_settings SET mode='test';
SET LOCAL ROLE authenticated;
SELECT request_product_activation('menu');
SELECT throws_ok($$SELECT create_subscription_checkout('84000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000002','menu')$$,'P0001','location_not_in_org','foreign location denied');
SELECT throws_ok($$SELECT create_subscription_checkout('84000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','pos')$$,'P0001','invalid_product','only supported digital products');
INSERT INTO checkout_results VALUES ('first',create_subscription_checkout('84000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','menu'));
SELECT is((SELECT value->>'status' FROM checkout_results WHERE key='first'),'open','first purchase creates unpaid invoice');
SELECT is((SELECT (value->>'total_agorot')::INT FROM checkout_results WHERE key='first'),5782,'DB calculates amount including configured VAT');
SELECT is((SELECT value->>'mode' FROM checkout_results WHERE key='first'),'test','test invoice visibly distinguished');
SELECT is(create_subscription_checkout('84000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','menu'),(SELECT value FROM checkout_results WHERE key='first'),'same key same result');
SELECT is(create_subscription_checkout('84000000-0000-4000-8000-000000000002','82000000-0000-4000-8000-000000000001','menu')->>'invoice_id',(SELECT value->>'invoice_id' FROM checkout_results WHERE key='first'),'new tab key reuses open invoice');
SELECT throws_ok($$SELECT create_subscription_checkout('84000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','reservations')$$,'P0001','checkout_request_conflict','same key cannot change purchase');
SELECT is((SELECT status FROM subscriptions WHERE org_id=auth_org_id()),'suspended','initial subscription is inactive');
SELECT ok(NOT org_has_capability_at(auth_org_id(),'82000000-0000-4000-8000-000000000001','public_menu'),'unpaid invoice does not grant access');
SELECT is((SELECT count(*)::INT FROM organization_products WHERE org_id=auth_org_id()),0,'no aggregate entitlement before payment');
SELECT is(get_subscription_checkout((SELECT (value->>'invoice_id')::UUID FROM checkout_results WHERE key='first'))->>'status','open','merely reading invoice is not payment');
SET LOCAL request.jwt.claims = '{"sub":"83000000-0000-4000-8000-000000000002","app_metadata":{"org_id":"81000000-0000-4000-8000-000000000002"}}';
SELECT throws_ok($$SELECT get_subscription_checkout((SELECT (value->>'invoice_id')::UUID FROM checkout_results WHERE key='first'))$$,'P0001','checkout_not_found','foreign invoice read denied');
SELECT throws_ok($$SELECT cancel_subscription_checkout((SELECT (value->>'invoice_id')::UUID FROM checkout_results WHERE key='first'))$$,'P0001','checkout_not_found','foreign invoice cancel denied');
SELECT throws_ok($$SELECT create_subscription_checkout('84000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000002','menu')$$,'P0001','checkout_request_conflict','cross-org replay denied');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT is(record_provider_payment('manual','checkout-wrong',(SELECT (value->>'invoice_id')::UUID FROM checkout_results WHERE key='first'),1)->>'outcome','rejected','wrong amount cannot activate');
SELECT is(record_provider_payment('manual','checkout-currency',(SELECT (value->>'invoice_id')::UUID FROM checkout_results WHERE key='first'),5782,'USD')->>'outcome','rejected','wrong currency cannot activate');
SELECT is(record_provider_payment('manual','checkout-paid',(SELECT (value->>'invoice_id')::UUID FROM checkout_results WHERE key='first'),5782)->>'outcome','applied','confirmed exact payment activates');
RESET ROLE;
INSERT INTO checkout_results SELECT 'period',jsonb_build_object('end',current_period_end) FROM subscriptions WHERE org_id='81000000-0000-4000-8000-000000000001';
SELECT is((SELECT status FROM subscriptions WHERE org_id='81000000-0000-4000-8000-000000000001'),'active','subscription active after payment');
SELECT is((SELECT status FROM product_activation_requests WHERE org_id='81000000-0000-4000-8000-000000000001' AND product='menu'),'approved','paid activation closes interest request');
SELECT ok(org_has_capability_at('81000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','public_menu'),'paid product grants capability');
SELECT ok(NOT org_has_capability_at('81000000-0000-4000-8000-000000000002','82000000-0000-4000-8000-000000000002','public_menu'),'other organization unchanged');
SET LOCAL ROLE service_role;
SELECT is(record_provider_payment('manual','checkout-paid',(SELECT (value->>'invoice_id')::UUID FROM checkout_results WHERE key='first'),5782)->>'outcome','duplicate','same event deduplicated');
SELECT is(record_provider_payment('manual','checkout-paid-again',(SELECT (value->>'invoice_id')::UUID FROM checkout_results WHERE key='first'),5782)->>'outcome','duplicate','different event for paid invoice deduplicated');
RESET ROLE;
SELECT is((SELECT current_period_end FROM subscriptions WHERE org_id='81000000-0000-4000-8000-000000000001'),(SELECT (value->>'end')::TIMESTAMPTZ FROM checkout_results WHERE key='period'),'retries never extend twice');
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claims = '{"sub":"83000000-0000-4000-8000-000000000001","app_metadata":{"org_id":"81000000-0000-4000-8000-000000000001"}}';
SELECT is(cancel_subscription_checkout((SELECT (value->>'invoice_id')::UUID FROM checkout_results WHERE key='first'))->>'status','paid','cancel cannot undo confirmed payment');
INSERT INTO checkout_results VALUES ('renew',create_subscription_checkout('84000000-0000-4000-8000-000000000003','82000000-0000-4000-8000-000000000001','menu'));
SELECT isnt((SELECT value->>'invoice_id' FROM checkout_results WHERE key='renew'),(SELECT value->>'invoice_id' FROM checkout_results WHERE key='first'),'explicit renewal gets a new invoice');
SELECT is(cancel_subscription_checkout((SELECT (value->>'invoice_id')::UUID FROM checkout_results WHERE key='renew'))->>'status','void','unpaid invoice can be canceled');
SELECT is(create_subscription_checkout('84000000-0000-4000-8000-000000000003','82000000-0000-4000-8000-000000000001','menu')->>'status','void','retry of canceled request cannot silently create new invoice');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT is(record_provider_payment('manual','checkout-void',(SELECT (value->>'invoice_id')::UUID FROM checkout_results WHERE key='renew'),5782)->>'outcome','rejected','late payment for void invoice rejected');
RESET ROLE;
UPDATE organization_members SET role='manager' WHERE auth_user_id='83000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT throws_ok('SELECT get_subscription_catalog()','P0001','billing_owner_required','manager cannot manage billing');
RESET ROLE;
UPDATE organization_members SET role='owner',is_active=false WHERE auth_user_id='83000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT throws_ok('SELECT get_subscription_catalog()','P0001','billing_owner_required','revoked owner denied with stale JWT');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
